from pathlib import Path
import json,statistics
out=Path('outputs/tree-end-to-end-study');rows=json.loads((out/'summary.json').read_text());assert len(rows)==6
rs={r['name']:r for r in rows};raw=[json.loads(x) for x in (out/'results.jsonl').read_text().splitlines()];rr={r['name']:r for r in raw}
names={'direct64':'两叶节点直接交给中心','forward64':'中继逐条转发 64符号','aggregate64':'中继两条合包 64符号','aggregate32':'中继两条合包 32符号','aggregate64-fast':'中继两条合包 64符号 缩短等待','aggregate32-fast':'中继两条合包 32符号 缩短等待'}
a=rs['aggregate64'];b=rs['aggregate32'];best=min([r for r in rows if r['mode']==3],key=lambda r:(-r['pdr'],r['window300']['mean_ms']))
def f(v):return f'{v:.3f}'
def pct(v):return f'{v*100:.3f}%'
lines=[]
def p(s=''):lines.append(s)
def table(head,data):
 block=['| '+' | '.join(head)+' |','| '+' | '.join(['---']*len(head))+' |']
 for row in data:block.append('| '+' | '.join(map(str,row))+' |')
 p('\n'.join(block))
p('# 四板电芯到中继再到中心的全过程实验')
p('\n实验日期：2026 年 11 月 4 日。正式测试 6 组，每组 50,000 条四字节叶节点数据。\n')
p('## 结论')
p(f'两个叶节点先把数据交给中继，中继合成一个包交给中心，这条完整路径已经跑通。64 符号、1000 μs 回复等待下，每轮拿到两个叶节点的数据平均需要 **{f(a["group_mean_ms"])} ms**。')
p(f'本次聚合测试中，平均耗时最短且到达率最高的配置是“{names[best["name"]]}”，每轮两个叶节点平均 **{f(best["group_mean_ms"])} ms**。按每组两个电芯、同一信道各组依次采集计算，200 个电芯平均需要 **{f(best["window200"]["mean_ms"])} ms**，300 个电芯平均需要 **{f(best["window300"]["mean_ms"])} ms**。当前实现达不到 100 ms 内收齐 200～300 个电芯数据的要求。')
p('本次证明了真实采集加聚合转发可以工作，也测出了完整过程的时间成本。后续应先减少叶节点采集和控制等待，再评估更大分组或并行信道。\n')
p('## 这次具体怎样做')
p('四块板分工如下。C、D 模拟两个电芯的数据源，每次被点名时生成本轮的 4 字节测试值；没有连接电芯传感器，因此本次计时不包含传感器采样。\n')
table(['板','角色','工作'],[['A','中心','发起采集，核对最终收到的数据'],['B','中继','点名 C、D，把实际收到的值存进缓存，再转发给 A'],['C','叶节点一','收到点名后生成并发送本轮数据'],['D','叶节点二','收到点名后生成并发送本轮数据']])
p('```text\nC 叶节点 ──实际无线发送──┐\n                       B 中继 ──实际无线发送── A 中心\nD 叶节点 ──实际无线发送──┘\n```\n')
p('一次完整采集按以下顺序进行：\n')
p('1. A 通知 B，开始收集本轮 C、D 的数据。\n2. B 点名 C；C 回复四字节数据。没收到时，B 再点名。\n3. B 点名 D；D 同样回复。B 保存从无线帧里读到的原始值。\n4. 在逐条转发组，B 每收到一条就转发；在合包组，B 收集后将两条放进同一个包。\n5. A 校验数据来源、本轮序号和内容。缺失时再次请求 B；B 可以重新转发本轮已收到的数据。\n6. 完成本轮的确认和结束控制后，再开始下一轮。\n')
p('**计时从 A 开始本轮采集前启动，到 A 完成本轮确认并结束规定等待为止。** 叶节点采集、无线传输、中继缓存和打包、补发、结束通知、确认及程序等待都包括在内。\n')
p('B 转发的是收到的缓存内容。某个叶节点没有交出本轮数据，B 就不会把它列为已经收到。测试程序用实验号、轮号、节点号生成可核对的数据，以检查旧数据、串轮和内容错误。\n')
p('## 对照条件和每组测了多少')
p('共同条件：UWB 信道 5，6.8 Mbps，PRF 64，STS 关闭；控制帧 30 B，单条数据帧 34 B，两条聚合帧 38 B，均包含 FCS。本轮使用现场自然丢包，未叠加此前蓝牙对照中的 10% 人工丢包。\n')
table(['实验','前导码符号数','叶节点回复等待 μs','为什么测'],[[names[r['name']],r['preamble'],r['reply_marker_delay_us'],{0:'建立直接上报基准',2:'测经过中继但不合包的代价',3:'测真实采集后合包的总时间'}[r['mode']]] for r in rows])
p('“回复等待”是收到点名后安排回复的时间参数，按芯片收发时间标记设置；它与两帧之间的空闲间隔 IFS 是不同的量。750 μs 组只调整这个参数，其他控制等待保持一致。\n')
p('每组有 25,000 轮，每轮采集 C、D 各一条，共 50,000 条。重传次数另外记录。合包组成功转发一包包含两条，因此这里的 50,000 指叶节点原始数据量；比较各组时保持业务量相同。中心和中继每次请求最多尝试五次，达到上限后记录缺失并继续。\n')
p('## 实际结果')
table(['做法','收两个叶节点平均 ms','一轮两个都收到','最终数据到达率','按平均速度100ms能收多少电芯的数据'],[[names[r['name']],f(r['group_mean_ms']),pct(r['all_groups_received']),pct(r['pdr']),r['capacity_by_mean_even_groups']] for r in rows])
p('最后一列按完整的“两电芯一组”向下取整，计算方法为：100 ms ÷ 每组平均耗时，取整后乘 2。它是按平均速度得到的容量预算，超时和完整收到的情况在下面单独统计。\n')
gain=(1-a['group_mean_ms']/rs['forward64']['group_mean_ms'])*100
p(f'在相同 64 符号和 1000 μs 等待下，合包相对逐条转发减少约 **{gain:.2f}%** 的整轮时间。叶节点到中继的两次上报仍然需要完成；合包主要节省中继到中心的一次数据发送。\n')
p(f'前导码从 64 缩到 32 时，标准等待下的整轮均值从 {f(a["group_mean_ms"])} ms 变为 {f(b["group_mean_ms"])} ms；中心额外请求从 {a["root_retries"]} 次变为 {b["root_retries"]} 次。该对照同时记录了缩短空口时间的收益和补发造成的成本。\n')
p('### 一轮时间花在哪里')
tree=[r for r in rows if r['mode']==3]
table(['配置','B 收集两叶数据 ms','B 准备及发送聚合包 ms','其他控制等待和处理 ms','A 测得全程 ms'],[[names[r['name']],f(r['leaf_collection_ms_per_group']),f(r['relay_uplink_work_ms_per_group']),f(r['other_control_wait_processing_ms_per_group']),f(r['group_mean_ms'])] for r in tree])
p('前两列由 B 的本地计时器累计，再除以采集轮数；包含相应阶段的重试。“发送聚合包”包括准备、200 μs 等待和发送调用的处理，并非纯空口时间。第三列为 A 的整轮时间减去前两列，包含中心指令、确认、结束通知、其余等待和处理。\n')
p('当前程序保留的控制等待包括：中继转发前 200 μs；确认前 200 μs、确认后 500 μs；中继发结束通知前 1000 μs。中心等待中继结束通知的上限为 60 ms，通知丢失会拉长个别轮次。以上时间均已进入结果。\n')
p('## 怎样推算 200 和 300 个电芯')
p('设定是：**每个电芯每 100 ms 上报一次四字节数据，同一信道的各组依次工作，每个中继负责两个电芯。** 200 个电芯对应 100 组；300 个电芯对应 150 组。中继和中心不计入这些电芯数据源数量。\n')
p('硬件实际只有 C、D 两个叶节点。程序连续运行同一组，把连续 100 组、150 组的完整实测时间分别记录下来，用作 200、300 个电芯依次采集的时间预算。它保留了过程中出现的重试和慢轮次。真实部署中的多个中继、不同距离、入网、同步和信道竞争尚需增加硬件验证。\n')
table(['配置','200 电芯平均预算 ms','200 电芯 P99 ms','300 电芯平均预算 ms','300 电芯 P99 ms'],[[names[r['name']],f(r['window200']['mean_ms']),f(r['window200']['p99_ms']),f(r['window300']['mean_ms']),f(r['window300']['p99_ms'])] for r in rows])
p('每组正式实验得到 250 段“200 条数据”的时间记录，以及 166 段完整的“300 条数据”记录。P99 表示这批记录中约 99% 在该时间内结束，直接取连续采集段的分位数。\n')
table(['配置','200 条全部收到比例','200 条在100ms内全部收到','300 条全部收到比例','300 条在100ms内全部收到'],[[names[r['name']],pct(r['window200']['all_received_rate']),pct(r['window200']['all_received_in_100ms']),pct(r['window300']['all_received_rate']),pct(r['window300']['all_received_in_100ms'])] for r in rows])
p(f'要让 200 个电芯在 100 ms 内收齐，每个“两电芯组”的全过程平均预算只有 **1 ms**；300 个电芯时只有 **0.667 ms**。本次最快聚合配置的平均值为 **{f(best["group_mean_ms"])} ms**，分别需要约 **{best["group_mean_ms"]:.1f} 倍**、**{best["group_mean_ms"]/.6666667:.1f} 倍** 的整体提速，才能达到平均时间目标。P99 和丢包要求还需一起满足。\n')
p('## 两项功能检查说明了什么')
fault=rr['smoke-missing-leaf'];fa=fault['boards']['A']
p(f'第一，让 D 在第 50～59 轮不回复。共测试 600 条，中心记录 C 缺失 **{fa["node_missing_3"]}** 条、D 缺失 **{fa["node_missing_4"]}** 条，与设定一致。这说明中继不会拿其他轮的数据填补本轮缺失；D 恢复后能够继续采集。\n')
p('第二，把回复等待缩到 500 μs。64 和 32 符号短测试都未收到叶节点数据，叶节点记录了错过计划发送时刻。这是当前程序准备回复的速度限制。750 μs 短测试没有出现该问题，随后进入正式测试。\n')
p('## 与此前约 67 ms 的结果有什么关系')
p('此前约 67 ms 测的是：发送板预先准备十条数据，每包十条地交给中心，累计交付 300 条。本次测的是：两个真实叶节点先通过无线把数据交给中继，中继每包合并两条，再交给中心。两次实验同时改变了“是否包含组内采集”和“每包条数”，不能把全部耗时差异都归因于叶节点采集。本次的阶段计时用于直接看组内采集花了多少时间。\n')
p('## 下一步怎么做')
p('当前每轮成功收集两个叶节点，即使完全不丢包，也要发送九帧：中心采集命令一帧、中继点名两帧、叶节点数据两帧、聚合数据一帧、中继确认一帧、中继结束通知一帧、中心确认一帧。短测试的实际发射计数与九帧一致。')
air=json.loads((out/'air-budget.json').read_text())['rows']
table(['前导码','九帧纯空口时间 μs','200 电芯纯空口预算 ms','300 电芯纯空口预算 ms'],[[r['preamble'],f(r['air_only_group_us']),f(r['air_only_200_ms']),f(r['air_only_300_ms'])] for r in air])
p('这是对当前九帧流程的理想下限计算：所有组串行，暂时把主控处理、帧间空闲和丢包都设为零。300 个电芯仍超过 100 ms，所以需要减少每组帧数或改变分组、并行方式，同时优化处理速度。空口计算采用 [Qorvo DW3000 数据手册 Table 18 和 Section 4.5](https://www.mouser.com/catalog/specsheets/Qorvo_DW3000.pdf) 的符号时间和帧格式。\n')
p('1. 先优化当前两叶节点组：提前准备帧、减少 SPI 往返、缩短接收处理与回复安排，逐段测量能省多少时间。优先消除毫秒级控制等待。\n2. 再验证一次通知、多个叶节点按时隙回复，减少逐个点名的控制帧。保持实际采集和丢包补发，重新测整轮时间。\n3. 增加叶节点后再比较每组 5、10 个的完整采集。每组节点数应由这类实测选择，十个来自此前同学的对照参数。\n4. 如需并行信道，再验证不同组同时工作的收发条件与干扰。当前单信道结果不乘以假设的信道数量。\n')
p('## 可直接向老师汇报')
p(f'> 我用四块板做了两个叶节点先上报给中继、中继再合包交给中心的完整实验。每组测试五万条数据，把采集、补发、打包和控制等待都计入。当前最快聚合配置收两个叶节点平均需要 {f(best["group_mean_ms"])} 毫秒。按同信道、两节点一组依次采集的方式推算，200 个电芯约需 {best["window200"]["mean_ms"]:.0f} 毫秒，300 个约需 {best["window300"]["mean_ms"]:.0f} 毫秒，尚未达到 100 毫秒目标。实验验证了真实两跳聚合可工作，后续主要优化叶节点采集和控制等待，再验证更大的分组。\n')
p('## 数据和代码')
p('- [原始记录 results.jsonl](tree-end-to-end-study/results.jsonl)：各板计数、接收位图统计、整轮直方图、连续 200/300 条时间记录。\n- [汇总 summary.json](tree-end-to-end-study/summary.json)：本文数值和阶段计时。\n- [测试后核对记录](tree-end-to-end-study/post-test-verification.json)：固件、配置和计数核对。\n- [代码及备份压缩包](四板全过程实验数据与代码.zip)：新 Tree 工程、脚本、原固件及原代码备份。')
